//go:build darwin

package network

import (
	"fmt"
	"log/slog"
	"net"
	"strings"

	"golang.zx2c4.com/wireguard/wgctrl"
)

// reapply is invoked by the route monitor on network change events.
// It re-runs the parts of Connect that depend on the upstream default gateway.
//
// CRITICAL: This function only does work when the upstream default gateway
// has ACTUALLY changed since the last time we pinned our bypass routes. The
// route monitor fires on any RTM_* event, including ones generated by our
// own `route add` commands during Connect and by unrelated OS chatter. Doing
// a full delete+readd cycle on every spurious event creates a routing loop
// window where WG encrypted packets go through the tunnel itself, and the
// connection appears dead. Comparing against lastGatewayV4/V6 turns those
// spurious firings into cheap no-ops.
func (m *DarwinManager) reapply() {
	m.routeMu.Lock()
	defer m.routeMu.Unlock()
	// Single-shot snapshot of every field reapply will reference.
	// Slices are copied (append) so a concurrent RemoveRoutes that
	// nils m.lastDNS or m.lastEndpoints can't yank them out from
	// under us mid-loop. Without the copy, reapply could see a
	// partially-cleared state where iface was still non-empty but
	// dns/endpoints had already been wiped, leading to spurious
	// applyDNS calls against the stale interface.
	m.mu.Lock()
	iface := m.lastIface
	oldEndpoints := append([]string(nil), m.lastEndpoints...)
	dns := append([]string(nil), m.lastDNS...)
	mtu := m.lastMTU
	prevV4 := m.lastGatewayV4
	prevV6 := m.lastGatewayV6
	hasV4 := m.lastHasV4Default
	hasV6 := m.lastHasV6Default
	pinIface := m.pinInterface
	m.mu.Unlock()

	// Bail cleanly when RemoveRoutes won the race — we've already
	// dropped the lock and have nothing meaningful to re-apply.
	if iface == "" {
		return
	}

	// wg-quick's set_endpoint_direct_route re-reads endpoints from
	// `wg show <iface> endpoints` on every RTM event, because wireguard-go
	// can roam to a different endpoint IP after a handshake. We do the
	// same via wgctrl so bypass routes track the actual peer endpoint.
	liveEndpoints := collectLiveEndpoints(iface)
	if len(liveEndpoints) == 0 {
		// Interface may be gone — monitor loop will break on the next
		// ifconfig check. Use cached endpoints as fallback.
		liveEndpoints = oldEndpoints
	}

	// Probe the current upstream gateway for each family. These values are
	// reused below when re-installing bypass routes, avoiding a redundant
	// second pair of netstat calls.
	currentV4, currentV4Err := getDefaultGatewayFor(false)
	currentV6, currentV6Err := getDefaultGatewayFor(true)

	gatewayChanged := currentV4 != prevV4 || currentV6 != prevV6

	// Detect endpoint roaming: compare live endpoints against the set we
	// have bypass routes for. wg-quick diffs old vs new and only touches
	// changed entries; we do the same.
	endpointsChanged := !stringSetEqual(oldEndpoints, liveEndpoints)

	// Gateway equality does not prove that our host routes still exist.
	// Another route manager may have removed one, leaving /1 -> utun.
	repair := make(map[string]bool)
	if ifaceInfo, err := net.InterfaceByName(iface); err == nil {
		for _, endpoint := range liveEndpoints {
			r, err := lookupEndpointRoute(endpoint)
			gatewayAvailable := currentV4Err == nil && currentV4 != ""
			if strings.Contains(endpoint, ":") {
				gatewayAvailable = currentV6Err == nil && currentV6 != ""
			}
			if endpointRouteMissing(err) || (err == nil && (r.loopsThrough(ifaceInfo.Index) || (r.blocksTraffic() && gatewayAvailable))) {
				repair[endpoint] = true
			}
		}
	}
	needBypassUpdate := (hasV4 || hasV6) && (gatewayChanged || endpointsChanged || len(repair) > 0)

	if !needBypassUpdate {
		// No bypass work needed, but DNS may still need attention — macOS
		// can reassign DNS when switching network services. Verify before
		// rewriting: this branch runs on every route-table event.
		if len(dns) > 0 {
			if err := m.applyDNSIfDrifted(dns); err != nil {
				slog.Warn("reapply: applyDNSIfDrifted failed", "error", err)
			}
		}
		return
	}
	if m.endpointTrafficGuard != nil {
		m.endpointTrafficGuard(false)
		defer func() {
			reason, err := m.endpointRoutingLoop(liveEndpoints)
			if reason == "" && err == nil {
				m.endpointTrafficGuard(true)
			} else {
				slog.Error("endpoint route repair not verified; outer packets remain blocked", "reason", reason, "error", err)
			}
		}()
	}

	slog.Info("route monitor: reapplying bypass routes",
		"iface", iface,
		"gateway_changed", gatewayChanged,
		"endpoints_changed", endpointsChanged,
		"prev_v4", prevV4, "current_v4", currentV4,
		"prev_v6", prevV6, "current_v6", currentV6,
		"old_endpoints", oldEndpoints, "live_endpoints", liveEndpoints)

	// Build sets for diffing (mirrors wg-quick's old_endpoints / ENDPOINTS logic).
	oldSet := make(map[string]bool, len(oldEndpoints))
	for _, ep := range oldEndpoints {
		oldSet[ep] = true
	}
	newSet := make(map[string]bool, len(liveEndpoints))
	for _, ep := range liveEndpoints {
		newSet[ep] = true
	}

	// Keep live endpoint routes installed while changing their gateway.
	// addBypassForIP uses route change for an existing host route, avoiding
	// a delete-then-add interval in which /1 would point back at utun.
	m.mu.Lock()
	oldBypass := append([]string(nil), m.bypassEndpoints...)
	m.mu.Unlock()

	// Reuse the gateways already probed above — no need for a second pair
	// of netstat calls. If the gateway changed between the probe and now
	// (extremely unlikely), the next RTM event will trigger another reapply.
	newGwV4, newGwV4Err := currentV4, currentV4Err
	newGwV6, newGwV6Err := currentV6, currentV6Err
	newUpstreamIface := ""
	if pinIface {
		newUpstreamIface = getDefaultInterface()
	}
	m.mu.Lock()
	m.lastUpstreamIface = newUpstreamIface
	m.mu.Unlock()

	// Add bypass routes for endpoints that need (re-)installation:
	// - If gateway changed: update all live endpoints in place.
	// - If only endpoints changed: only newly appeared endpoints.
	//
	// Reapply is the network-state-change handler, NOT a fresh connect.
	// addBypassForIP now fail-fast-returns on missing gateway, which is
	// correct for Connect (rollback runs) but unsafe here — the /1 split
	// routes were already in force before this reapply began, and
	// returning without a /32 bypass would leave the encrypted-UDP path
	// matching /1 → utun → loop. So in reapply we install a blackhole
	// fallback when the new gateway is missing; the tunnel breaks
	// (handshake can't reach the peer) but the loop is contained.
	// Next RTM event with a real gateway promotes the blackhole back
	// to a real bypass.
	for _, ipStr := range liveEndpoints {
		if ipStr == "" {
			continue
		}
		if !gatewayChanged && oldSet[ipStr] && !repair[ipStr] {
			// Gateway didn't change and this endpoint already had a valid
			// bypass route (preserved above). Skip.
			continue
		}
		ip := net.ParseIP(ipStr)
		if ip == nil {
			continue
		}
		isV6 := ip.To4() == nil
		if isV6 && !hasV6 {
			continue
		}
		if !isV6 && !hasV4 {
			continue
		}
		if err := m.addBypassForIP(ipStr, newGwV4, newGwV6, newGwV4Err, newGwV6Err); err != nil {
			slog.Warn("reapply: bypass install failed; installing blackhole as a loop firewall",
				"ip", ipStr, "error", err)
			m.installBlackholeBypass(ipStr, isV6)
		}
	}
	// Retire old endpoints only after the current set has been protected.
	for _, ip := range oldBypass {
		if newSet[ip] {
			continue
		}
		family := "-inet"
		if strings.Contains(ip, ":") {
			family = "-inet6"
		}
		if err := run("route", "-q", "-n", "delete", family, ip); err != nil {
			slog.Debug("bypass route delete failed (may already be gone)", "ip", ip, "error", err)
		}
	}
	m.mu.Lock()
	kept := m.bypassEndpoints[:0]
	for _, ip := range m.bypassEndpoints {
		if newSet[ip] {
			kept = append(kept, ip)
		}
	}
	m.bypassEndpoints = kept
	m.mu.Unlock()

	// Update cached state including upstream interface for bypass -ifscope.
	// Resolve interface outside the lock to avoid blocking on netstat.
	// pinInterface was snapshotted at function entry — use that value
	// rather than re-reading the field, otherwise a concurrent
	// SetPinInterface flip mid-reapply could leave us with mixed state.
	m.mu.Lock()
	m.lastEndpoints = append([]string(nil), liveEndpoints...)
	m.lastGatewayV4 = newGwV4
	m.lastGatewayV6 = newGwV6
	m.lastUpstreamIface = newUpstreamIface
	m.mu.Unlock()

	if len(dns) > 0 {
		if err := m.applyDNS(dns); err != nil {
			slog.Warn("reapply: applyDNS failed after bypass update", "error", err)
		}
	}

	if mtu > 0 {
		if current := getInterfaceMTU(iface); current != mtu && current > 0 {
			if err := run("ifconfig", iface, "mtu", fmt.Sprintf("%d", mtu)); err != nil {
				slog.Warn("reapply: ifconfig mtu failed", "iface", iface, "mtu", mtu, "error", err)
			}
		}
	}
}

// collectLiveEndpoints reads the current peer endpoint IPs from the WireGuard
// interface via wgctrl, mirroring wg-quick's `wg show $REAL_INTERFACE endpoints`.
// Returns deduplicated IP strings (no port). Returns nil on any error.
func collectLiveEndpoints(ifaceName string) []string {
	client, err := wgctrl.New()
	if err != nil {
		slog.Debug("collectLiveEndpoints: wgctrl.New failed", "error", err)
		return nil
	}
	defer client.Close()

	dev, err := client.Device(ifaceName)
	if err != nil {
		slog.Debug("collectLiveEndpoints: Device() failed", "iface", ifaceName, "error", err)
		return nil
	}

	seen := make(map[string]bool)
	var eps []string
	for _, peer := range dev.Peers {
		if peer.Endpoint == nil {
			continue
		}
		ip := peer.Endpoint.IP.String()
		if !seen[ip] {
			seen[ip] = true
			eps = append(eps, ip)
		}
	}
	return eps
}

// stringSetEqual returns true if two string slices contain the same elements
// (order-independent).
func stringSetEqual(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	set := make(map[string]int, len(a))
	for _, s := range a {
		set[s]++
	}
	for _, s := range b {
		set[s]--
		if set[s] < 0 {
			return false
		}
	}
	return true
}
